expression:
grel:if(
  toString(value) != "active",
  value,
  if(
    and(
      toString(cells['Patron_User_ID_At_Source'].value).toLowercase().contains("@bethanywv.edu"),
      toString(cells['Patron_Source_System'].value).contains("https://sts.windows.net/e7f0b6cf-3723-46f1-a1ea-e81e6753374d/")
    ),
    value + " - verified",
    value + " - review_source"
  )
)

